import React, { useState, useEffect } from 'react';
import { Star, Plus, Search, User, LogIn, Home, Beer, Users, ChevronRight, Heart, MessageCircle, TrendingUp } from 'lucide-react';
import { api } from './services/api';

const BeerReviewApp = () => {
  const [currentPage, setCurrentPage] = useState('home');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState(null);
  const [beers, setBeers] = useState([
    {
      id: 1,
      name: "Hoppy IPA",
      brewery: "Local Craft Brewery",
      style: "IPA",
      abv: 6.5,
      ibu: 65,
      rating: 4.2,
      reviews: 24,
      image: "https://via.placeholder.com/300x400/8B4513/FFFFFF?text=Beer"
    },
    {
      id: 2,
      name: "Smooth Stout",
      brewery: "Dark Mountain Brewing",
      style: "Stout",
      abv: 5.8,
      ibu: 35,
      rating: 4.5,
      reviews: 31,
      image: "https://via.placeholder.com/300x400/2F1B14/FFFFFF?text=Beer"
    },
    {
      id: 3,
      name: "Golden Wheat",
      brewery: "Sunshine Brewery",
      style: "Wheat",
      abv: 4.8,
      ibu: 20,
      rating: 3.8,
      reviews: 18,
      image: "https://via.placeholder.com/300x400/DAA520/FFFFFF?text=Beer"
    }
  ]);
  const [searchTerm, setSearchTerm] = useState('');
  const [newBeer, setNewBeer] = useState({
    name: '',
    brewery: '',
    style: '',
    abv: '',
    ibu: '',
    notes: ''
  });
  const [userRating, setUserRating] = useState(0);
  const [userReview, setUserReview] = useState('');

  // Test API connection on app load
  useEffect(() => {
    const testConnection = async () => {
      try {
        const result = await api.test();
        console.log('✅ Backend connected:', result);
      } catch (error) {
        console.error('❌ Backend connection failed:', error);
      }
    };

    testConnection();
  }, []);

  const StarRating = ({ rating, onRate, interactive = false, size = 'w-5 h-5' }) => {
    return (
      <div className="flex items-center gap-1">
        {[1, 2, 3, 4, 5].map((star) => (
          <Star
            key={star}
            className={`${size} ${
              star <= rating 
                ? 'text-yellow-400 fill-yellow-400' 
                : 'text-gray-300'
            } ${interactive ? 'cursor-pointer hover:text-yellow-400' : ''}`}
            onClick={() => interactive && onRate && onRate(star)}
          />
        ))}
      </div>
    );
  };

  const BeerCard = ({ beer, onClick }) => (
    <div 
      className="bg-white rounded-xl shadow-xl overflow-hidden hover:shadow-2xl transition-all duration-500 cursor-pointer transform hover:scale-105 border-4 border-cream hover:border-red-500"
      onClick={() => onClick(beer)}
    >
      <div className="aspect-w-3 aspect-h-4 bg-gradient-to-br from-gray-100 to-gray-200 relative">
        <img 
          src={beer.image} 
          alt={beer.name}
          className="w-full h-48 object-cover"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent"></div>
      </div>
      <div className="p-5 bg-white">
        <h3 className="font-bold text-xl text-red-800 mb-2 font-serif">{beer.name}</h3>
        <p className="text-red-600 font-semibold mb-3 text-lg">{beer.brewery}</p>
        <div className="flex items-center justify-between mb-3">
          <span className="text-sm font-bold text-red-700 bg-cream px-3 py-1 rounded-full border-2 border-red-200">{beer.style}</span>
          <span className="text-sm font-bold text-red-800 bg-red-50 px-2 py-1 rounded">{beer.abv}% ABV</span>
        </div>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <StarRating rating={beer.rating} />
            <span className="text-sm font-semibold text-red-700">({beer.reviews})</span>
          </div>
          <ChevronRight className="w-5 h-5 text-red-600" />
        </div>
      </div>
    </div>
  );

  const Navigation = () => (
    <nav className="bg-gradient-to-r from-red-700 via-red-600 to-red-700 text-white p-4 shadow-xl border-b-4 border-cream">
      <div className="max-w-6xl mx-auto flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-cream rounded-full flex items-center justify-center shadow-lg border-2 border-white">
            <Beer className="w-6 h-6 text-red-800" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-white tracking-wide font-serif">Red Robin Brewing Co.</h1>
            <p className="text-cream text-sm italic">Est. Since You Started Drinking Good Beer</p>
          </div>
        </div>
        <div className="flex items-center gap-6">
          <button 
            onClick={() => setCurrentPage('home')}
            className={`flex items-center gap-2 px-4 py-2 rounded-full transition-all duration-300 font-semibold border-2 ${
              currentPage === 'home' 
                ? 'bg-cream text-red-800 border-white shadow-lg' 
                : 'border-cream text-cream hover:bg-cream hover:text-red-800 hover:border-white'
            }`}
          >
            <Home className="w-4 h-4" />
            Home
          </button>
          <button 
            onClick={() => setCurrentPage('search')}
            className={`flex items-center gap-2 px-4 py-2 rounded-full transition-all duration-300 font-semibold border-2 ${
              currentPage === 'search' 
                ? 'bg-cream text-red-800 border-white shadow-lg' 
                : 'border-cream text-cream hover:bg-cream hover:text-red-800 hover:border-white'
            }`}
          >
            <Search className="w-4 h-4" />
            Search
          </button>
          <button 
            onClick={() => setCurrentPage('add')}
            className={`flex items-center gap-2 px-4 py-2 rounded-full transition-all duration-300 font-semibold border-2 ${
              currentPage === 'add' 
                ? 'bg-cream text-red-800 border-white shadow-lg' 
                : 'border-cream text-cream hover:bg-cream hover:text-red-800 hover:border-white'
            }`}
          >
            <Plus className="w-4 h-4" />
            Add Beer
          </button>
          {isLoggedIn ? (
            <button 
              onClick={() => setCurrentPage('profile')}
              className="flex items-center gap-2 px-4 py-2 rounded-full transition-all duration-300 font-semibold border-2 border-cream text-cream hover:bg-cream hover:text-red-800 hover:border-white"
            >
              <User className="w-4 h-4" />
              Profile
            </button>
          ) : (
            <button 
              onClick={() => setCurrentPage('login')}
              className="flex items-center gap-2 px-4 py-2 rounded-full transition-all duration-300 font-semibold border-2 border-cream text-cream hover:bg-cream hover:text-red-800 hover:border-white"
            >
              <LogIn className="w-4 h-4" />
              Login
            </button>
          )}
        </div>
      </div>
    </nav>
  );

  const HomePage = () => (
    <div className="min-h-screen bg-white">
      <div className="max-w-6xl mx-auto p-6">
        <div className="text-center mb-12">
          <div className="relative mb-8">
            <h2 className="text-6xl font-bold text-red-800 mb-4 font-serif tracking-wide drop-shadow-lg">
              Welcome to Red Robin Brewing Co.
            </h2>
            <div className="absolute -top-2 -left-2 w-full h-full text-6xl font-bold text-cream font-serif tracking-wide -z-10">
              Welcome to Red Robin Brewing Co.
            </div>
          </div>
          <p className="text-2xl text-red-700 mb-8 font-medium italic">
            "Where every sip tells a story, and every story deserves a cold one"
          </p>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-16">
